const lv_image_dsc_t *mascot_for(const char *mood)
{
    if(mood && strcmp(mood, "sleepy") == 0) return &mascot_sleepy;
    if(mood && strcmp(mood, "chill") == 0) return &mascot_chill;
    if(mood && strcmp(mood, "pumped") == 0) return &mascot_pumped;
    if(mood && strcmp(mood, "proud") == 0) return &mascot_proud;
    if(mood && strcmp(mood, "tired") == 0) return &mascot_tired;
    return &mascot_chill;
}
